#' Plausibly Exogenous Instruments
#'
#' 
#' @param data .
#' @param outcome .
#' @param endog .
#' @param instruments .
#' @param controls .
#' @param absorb .
#' @param cluster .
#' @param weights .
#' @param vce .
#' @param small .
#' @param delta .
#' @param ltzMean .
#' @param ltzSd .
#' @param level .
#' @param plot .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$tip} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$uci} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$ltz} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plausPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$tip$asDF}
#'
#' \code{as.data.frame(results$tip)}
#'
#' @export
ivplaus <- function(
    data,
    outcome,
    endog,
    instruments,
    controls,
    absorb,
    cluster,
    weights,
    vce = "classical",
    small = TRUE,
    delta = 0,
    ltzMean = 0,
    ltzSd = 0,
    level = 95,
    plot = TRUE,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("ivplaus requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(endog)) endog <- jmvcore::resolveQuo(jmvcore::enquo(endog))
    if ( ! missing(instruments)) instruments <- jmvcore::resolveQuo(jmvcore::enquo(instruments))
    if ( ! missing(controls)) controls <- jmvcore::resolveQuo(jmvcore::enquo(controls))
    if ( ! missing(absorb)) absorb <- jmvcore::resolveQuo(jmvcore::enquo(absorb))
    if ( ! missing(cluster)) cluster <- jmvcore::resolveQuo(jmvcore::enquo(cluster))
    if ( ! missing(weights)) weights <- jmvcore::resolveQuo(jmvcore::enquo(weights))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(endog), endog, NULL),
            `if`( ! missing(instruments), instruments, NULL),
            `if`( ! missing(controls), controls, NULL),
            `if`( ! missing(absorb), absorb, NULL),
            `if`( ! missing(cluster), cluster, NULL),
            `if`( ! missing(weights), weights, NULL))


    options <- ivplausOptions$new(
        outcome = outcome,
        endog = endog,
        instruments = instruments,
        controls = controls,
        absorb = absorb,
        cluster = cluster,
        weights = weights,
        vce = vce,
        small = small,
        delta = delta,
        ltzMean = ltzMean,
        ltzSd = ltzSd,
        level = level,
        plot = plot,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- ivplausClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

